SKIN_TONES = {
    "Fair": dict(red=(2, -12, 3), orange=(-2, -8, 3), yellow=(0, -6, 0), hi=-16, sh=8, why="very fair skin that blushes and clips easily: reduced red and orange saturation, protected highlights"),
    "Light": dict(red=(2, -8, 2), orange=(-2, -5, 3), yellow=(0, -4, 0), hi=-12, sh=8, why="light skin: gentle red control and a little orange lift"),
    "Medium": dict(red=(0, -5, 0), orange=(-1, -3, 2), yellow=(0, -4, 0), hi=-10, sh=10, why="medium skin: neutral red and orange handling"),
    "Olive": dict(red=(0, -4, 0), orange=(1, -2, 2), yellow=(-5, -10, 0), green=(0, -8, 0), hi=-10, sh=10, why="olive skin with green-yellow undertones: yellow shifted toward orange and green cast reduced, avoiding pushing to pure orange"),
    "Tan": dict(red=(0, -6, 0), orange=(-1, -4, 2), yellow=(-2, -6, 0), hi=-12, sh=10, why="tan skin: keeps the warmth without orange overload"),
    "Deep": dict(red=(0, -4, 0), orange=(0, -3, 0), yellow=(0, -6, 0), hi=-8, sh=6, why="deep skin: no lightening of luminance, red and orange saturation controlled, healthy specular highlights preserved"),
}

for _tone, _d in SKIN_TONES.items():
    _mx = {k: _d[k] for k in ("red", "orange", "yellow", "green") if k in _d}
    _skin = dict(hueUniformity=10, satUniformity=12, lumUniformity=8 if _tone == "Deep" else 14)
    LIBRARY_2.append(P("Skin Tones", f"{_tone} Skin Natural", f"Base for {_d['why']}. Uses mixer only, no white balance change. Use with correct exposure; do not use as a lightening tool.", f"skin tone {_tone.lower()} natural portrait",
      mixer=mix(**_mx), light={"highlights": _d["hi"], "shadows": _d["sh"]}, skin=_skin))
    _w = {k: (v[0], v[1] - 4 if k in ("orange", "red") else v[1], v[2]) for k, v in _mx.items()}
    LIBRARY_2.append(P("Skin Tones", f"{_tone} Skin Golden Light", f"For {_tone.lower()} skin in warm golden hour or sunset light, which pushes skin orange: lowers orange and red saturation further and rolls highlights.", f"skin tone {_tone.lower()} golden warm sun",
      mixer=mix(**_w), light={"highlights": _d["hi"] - 8, "shadows": _d["sh"] + 4}, skin=_skin, grading=g(hi=(40, 6), blending=45)))
    LIBRARY_2.append(P("Skin Tones", f"{_tone} Skin Cool Shade", f"For {_tone.lower()} skin in open shade, overcast or cool window light: restores warmth through grading and a mild vibrance lift, leaving white balance alone.", f"skin tone {_tone.lower()} shade cool overcast",
      mixer=mix(**_mx), grading=g(mid=(30, 6), hi=(38, 8), blending=55), light={"highlights": _d["hi"] + 4, "shadows": _d["sh"]}, color={"vibrance": 5}, skin=_skin))
    LIBRARY_2.append(P("Skin Tones", f"{_tone} Skin Matte Editorial", f"Editorial matte treatment for {_tone.lower()} skin: soft blacks without grey or ashy cast, mild saturation reduction and restrained mixer values.", f"skin tone {_tone.lower()} matte editorial",
      mixer=mix(**_mx), curve={"master": SOFT_MATTE}, color={"saturation": -6}, light={"contrast": -4, "highlights": _d["hi"] + 4}, grading=g(mid=(30, 4), blending=45), skin=_skin))

